        '가지치기의 연쇄 균열 → 갈래 베기 → 십자 강타. 빙결 지대를 벗어난 뒤 마무리의 빈틈을 노립니다.': '修剪的連鎖裂痕 → 分叉斬 → 十字重擊。離開冰封地帶後，抓住收尾後的破綻。',
