        '어군 추적': '魚群追蹤',
        '흔한 어종을 빠르게 모으지만 희귀 어종을 만날 확률이 낮아집니다.': '快速收集常見魚種，但遇到稀有魚種的機率降低。',
        '심연 투망': '深淵撒網',
