        '위협을 낮춰 처음 연결하는 항로입니다.': '降低威脅、首次連接的航線。',
        '성간 잔해를 회수해 탐사 보상을 높입니다.': '回收星際殘骸以提高探索獎勵。',
        '강한 개체를 추적해 밀도 높은 보상을 노립니다.': '追蹤強大個體以獲取高密度獎勵。',
        '불안정한 균열을 가로질러 큰 수익을 노립니다.': '穿越不穩定的裂隙以博取高收益。',
        '빨라지는 성운 폭풍 속에서 공명 잔광을 수확합니다.': '在加速的星雲風暴中收穫共鳴餘暉。',
        '드물게 관측되는 흑성 신호입니다. 위험과 보상이 크게 증폭됩니다.': '罕見觀測到的黑星信號。危險與獎勵大幅增強。',
        '봉인된 보물함': '封印的寶箱',
        '이제 탐험 중 봉인된 보물함을 발견할 수 있습니다.': '現在探索時可以發現封印的寶箱。',
        '매복': '埋伏',
        '이제 탐험 중 매복을 만날 수 있습니다.': '現在探索時可能遭遇埋伏。',
        '알집': '卵窩',
        '이제 탐험 중 알집을 발견할 수 있습니다.': '現在探索時可以發現卵窩。',
