        '루프 20': '循環 20',
        '밑거름의 우물 바닥에서 깨어난 뿌리없는 자가 잔뿌리 괴물들에게 습격당하던 은둔자 하켄을 구하고, 위쪽 중정으로 오르는 통로를 개척한다.': '在堆肥之井底醒來的無根者救下被細根怪物襲擊的隱士哈肯，並開闢通往上方中庭的通道。',
        '루프 21': '循環 21',
        '루프 22': '循環 22',
