        '루프 30': '循環 30',
        '중정의 수호자는 치명상을 입어도 황금 수액관이 맥동하는 한 몇 번이고 다시 일어선다.': '中庭的守護者即使身負致命傷，只要黃金樹液管仍在搏動，就會一次次重新站起。',
        '루프 31': '循環 31',
        '루프 32': '循環 32',
