        '루프 39': '循環 39',
        '루프 40': '循環 40',
        '모든 양분을 중정으로 수탈당해 아사 직전에 몰린 현수림을 가로질러 수액 수송로의 분기점을 찾는다.': '穿過被中庭掠奪盡養分、瀕臨餓死的懸林，尋找樹液運輸路線的分岔點。',
        '루프 41': '循環 41',
        '루프 42': '循環 42',
