        '“창공의 탑 꼭대기에 놓인 왕좌는 태초부터 주인이 없었다.”': '「蒼穹之塔頂端的王座，自太初起便沒有主人。」',
        '“텅 빈 왕좌의 질서를 수호하던 자동 집행자가 멈춰 서자, 수관 너머의 천공이 비로소 열렸다.”': '「守護空王座秩序的自動執行者停下時，樹冠之外的天空終於打開了。」',
        '경계의 관측자, 베일라': '邊界的觀測者，薇拉',
