        '원소 피해 +18%': '元素傷害 +18%',
        '세 스킬의 모든 타격에 물리 고정 피해가 더해지고 물리 피해 감소를 받습니다. 소환 한도 1을 쓰고, 가호는 하나만 걸립니다. 발밑에 ᚢ 룬이 떠오릅니다.': '三個技能的所有命中附加固定物理傷害，並獲得物理減傷。佔用1個召喚上限，加護只能生效一個。腳下浮現 ᚢ 符文。',
        '세 스킬의 모든 타격에 화염 고정 피해가 더해지고 화염 저항을 받습니다. 소환 한도 1을 쓰고, 가호는 하나만 걸립니다. 발밑에 ᛝ 룬이 떠오릅니다.': '三個技能的所有命中附加固定火焰傷害，並獲得火焰抗性。佔用1個召喚上限，加護只能生效一個。腳下浮現 ᛝ 符文。',
        '세 스킬의 모든 타격에 냉기 고정 피해가 더해지고 냉기 저항을 받습니다. 소환 한도 1을 쓰고, 가호는 하나만 걸립니다. 발밑에 ᛁ 룬이 떠오릅니다.': '三個技能的所有命中附加固定冰霜傷害，並獲得冰霜抗性。佔用1個召喚上限，加護只能生效一個。腳下浮現 ᛁ 符文。',
        '세 스킬의 모든 타격에 번개 고정 피해가 더해지고 번개 저항을 받습니다. 소환 한도 1을 쓰고, 가호는 하나만 걸립니다. 발밑에 ᛊ 룬이 떠오릅니다.': '三個技能的所有命中附加固定閃電傷害，並獲得閃電抗性。佔用1個召喚上限，加護只能生效一個。腳下浮現 ᛊ 符文。',
        '세 스킬의 모든 타격에 카오스 고정 피해가 더해지고 카오스 저항을 받습니다. 소환 한도 1을 쓰고, 가호는 하나만 걸립니다. 발밑에 ᛒ 룬이 떠오릅니다.': '三個技能的所有命中附加固定混沌傷害，並獲得混沌抗性。佔用1個召喚上限，加護只能生效一個。腳下浮現 ᛒ 符文。',
        '생명력이 천천히 차오르고 이동 속도가 오릅니다. 소환 한도 1을 쓰고, 가호는 하나만 걸립니다. 발밑에 ᛃ 룬이 떠오릅니다.': '生命緩緩回滿，移動速度提高。佔用1個召喚上限，加護只能生效一個。腳下浮現 ᛃ 符文。',
