        '빙결 파편 창을 꿰뚫어 쏘는 냉기 주문입니다. 냉각된 적에게 적중 시 냉각을 소모해 20% 증폭된 피해를 주고, 동결된 적에게 적중 시 동결을 소모해 40% 증폭된 피해를 줍니다.': '射出可穿透的冰凍碎片之槍的冰霜法術。命中受冰緩的敵人時消耗冰緩造成20%增幅傷害，命中被凍結的敵人時消耗凍結造成40%增幅傷害。',
