        '지속 피해 배율 +25%, 포션 스킬 피해 +30%, 중독 피해 +12%': '持續傷害倍率 +25%，藥水技能傷害 +30%，中毒傷害 +12%',
        '맞닿은 부적의 일반 줄을 25% 더 얻습니다.': '相鄰護身符的普通詞條額外獲得25%。',
        '표식 방향으로 맞닿은 부적의 일반 줄을 한 번 더 얻습니다.': '再獲得一次標記方向相鄰護身符的普通詞條。',
        '일반 줄 세 개를 굴림 배율 없이 가집니다.': '擁有三條無擲骰倍率的普通詞條。',
        '맞닿은 그루터기 아이템이 없으면 스킬룬 레벨과 보조스킬룬 한도 +1, 하나면 보조스킬룬 한도 +1, 둘 이상이면 피해 +15%와 공격 속도 +10%': '無相鄰樹樁物品時技能符文等級與輔助技能符文上限 +1，有一個時輔助技能符文上限 +1，有兩個以上時傷害 +15%、攻擊速度 +10%',
        '보스에게 주는 최종 피해가 늘어나고, 생명력 5% 이하인 보스를 즉시 쓰러뜨립니다.': '提高對Boss的最終傷害，並立即擊倒生命5%以下的Boss。',
        '세 칸 이상 떨어진 깨어난 부적의 일반 줄을 25% 더 얻습니다.': '相距三格以上的覺醒護身符的普通詞條額外獲得25%。',
        '맞닿은 그루터기 아이템 하나마다 받는 물리 피해 감소 +1%.': '每個相鄰樹樁物品使受到的物理傷害減免 +1%。',
        '둘레 여덟 칸(대각선 포함)의 깨어난 부적 일반 줄을 35% 더 얻습니다.': '周圍八格（含對角）覺醒護身符的普通詞條額外獲得35%。',
        '가로나 세로로 두 칸 떨어진 깨어난 부적의 일반 줄을 20% 더 얻습니다.': '橫向或縱向相距兩格的覺醒護身符的普通詞條額外獲得20%。',
        '그루터기 함에 성장 완료된 화염, 냉기, 번개 그루터기 아이템이 모두 있으면 원소 피해 +30%, 저항 관통 +6%.': '樹樁匣中同時擁有成長完成的火焰、冰霜、閃電樹樁物品時，元素傷害 +30%，抗性穿透 +6%。',
        '그루터기 함 가장자리에 닿은 면 하나마다 모든 원소 저항 +4%, 받는 물리 피해 감소 +2%. 모서리면 생명력 +10%.': '每有一面貼著樹樁匣邊緣，所有元素抗性 +4%，受到的物理傷害減免 +2%。位於角落則生命 +10%。',
        '맞닿은 씨앗의 서로 다른 색 하나마다 화염 피해 +8%, 3색 이상이면 저항 관통 +5%.': '相鄰種子每有一種不同顏色，火焰傷害 +8%；三色以上則抗性穿透 +5%。',
        '그루터기 함의 성장 완료된 씨앗 하나마다 이 부적의 일반 줄 +10%(최대 30%).': '樹樁匣中每個成長完成的種子使此護身符的普通詞條 +10%（最多30%）。',
        '그루터기 함에서 비활성화된 그루터기 아이템 하나마다 생명력 +5%, 방어도 +25(최대 4개).': '樹樁匣中每個被停用的樹樁物品使生命 +5%、護甲 +25（最多4個）。',
        '맞닿은 그루터기 아이템 하나마다 물리 피해 +7%, 생명력 −2%.': '每個相鄰樹樁物品使物理傷害 +7%，生命 −2%。',
        '같은 가로줄이나 세로줄에 있는 깨어난 부적의 일반 줄을 18% 더 얻습니다.': '同一行或同一列的覺醒護身符的普通詞條額外獲得18%。',
        '다른 깨어난 부적의 소환수 줄을 15% 더 얻고, 그런 부적이 4개 이상이면 소환수 한도 +1.': '其他覺醒護身符的召喚物詞條額外獲得15%，這類護身符達4個以上時召喚上限 +1。',
        '그루터기 함의 그루터기 아이템이 6개 이상이고 종류(계열과 색)가 모두 다르면 이 부적의 일반 줄 +40%.': '樹樁匣中樹樁物品達6個以上且種類（系列與顏色）全部不同時，此護身符的普通詞條 +40%。',
        '그루터기 함의 성장 완료된 카오스 그루터기 아이템 하나마다 카오스 피해와 지속 피해 +8%(최대 5개), 생명력 −10%.': '樹樁匣中每個成長完成的混沌樹樁物品使混沌傷害與持續傷害 +8%（最多5個），生命 −10%。',
