        '심해로 돌아가기': '返回深海',
        '수면으로 복귀': '返回水面',
        ' data-exploration-departure data-departure-title="수면으로 올라갈까요?" data-departure-message="{checkpointM}m 체크포인트 뒤의 진행은 사라집니다. 이미 얻은 물고기와 재화는 유지됩니다."': 'data-exploration-departure data-departure-title="要上浮到水面嗎？" data-departure-message="{checkpointM}m 檢查點之後的進度將消失。已獲得的魚與貨幣將保留。"',
