        '강화': '強化',
        '지금': '當前',
        '몬스터를 쓰러뜨린 만큼 내려갑니다. 정예는 {eliteKillMul}배입니다.': '擊殺多少怪物就下潛多少。精英計{eliteKillMul}倍。',
        '{value}m마다 길을 막고, 닿으면 남은 무리를 두고 바로 가디언 방으로 갑니다. 쓰러뜨려야 더 내려가고, 가디언에게 쓰러지면 잠수가 끝납니다.': '每{value}m擋路一次，到達後放下剩餘敵群直接進入守護者房間。必須擊倒才能繼續下潛，被守護者擊倒則潛水結束。',
        '초당 {st} 줄어들고, 철갑 패각충과 정예, 가디언이 부른 졸개를 쓰러뜨리면 공기 방울로 찹니다. 다 떨어지면 익사 피해를 받다가 수면으로 올라와 잠수를 시작한 사냥터로 돌아오고, 체크포인트 뒤 진행은 사라집니다.': '每秒減少{st}，擊倒鐵甲貝殼蟲、精英及守護者召喚的小怪可用氣泡補充。耗盡後受到溺水傷害並上浮，回到開始潛水的獵場，檢查點之後的進度消失。',
        '켜 두면 산소가 떨어지거나 가디언에게 쓰러져 떠오른 뒤, 사냥터 하나를 깨고 다시 잠수합니다. 가디언 앞에 막혔으면 지난 가디언 자리부터 내려가 물고기를 모읍니다. 무리에게 쓰러지거나, 리프트도 가디언 처치도 물고기도 없이 {missLimit}번 떠오르면 멈춥니다. 새 루프의 첫 잠수와 자리를 비운 동안의 정산에서는 다시 잠수하지 않습니다.': '開啟後，因氧氣耗盡或被守護者擊倒上浮後，會通關一個獵場並再次潛水。若被守護者擋住，則從上一個守護者位置下潛收集魚。被敵群擊倒，或在沒有升降、沒有擊倒守護者、沒有魚的情況下上浮{missLimit}次則停止。新循環的首次潛水與離線結算期間不會再次潛水。',
