        '장비를 눌러 효과를 확인하세요. 빈 칸에 맞는 장비는 이미 착용되어 있습니다. 바꿔 끼우고 싶을 때 ‘장착’을 누르세요.': '點擊裝備查看效果。適合空格的裝備已自動穿戴。想更換時請按「裝備」。',
