        '첫 스킬트리 포인트': '首個技能樹點數',
        "레벨이 올라 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.\n오른 능력치는 ‘캐릭터’에서 확인할 수 있습니다.": "升級獲得了技能樹點數。\n請在「技能樹」中選擇與起點相連的節點點亮。\n提升的屬性可在「角色」中查看。",
        '첫 장비': '首件裝備',
        "장비를 얻었습니다. 자동 장착이 켜져 있으면 빈 칸에 맞는 장비를 바로 착용합니다.\n‘장비’에서 착용한 장비의 효과를 확인하고, 보관 중인 장비와 비교하세요.\n바꿔 입으면 전투 화면의 생명 구슬 위에 DPS 변화가 뜹니다.": "獲得了裝備。開啟自動裝備時會立即穿戴適合空格的裝備。\n請在「裝備」中查看已穿戴裝備的效果，並與倉庫中的裝備比較。\n更換後戰鬥畫面生命球上方會顯示DPS變化。",
        '무기와 스킬룬': '武器與技能符文',
        "스킬룬마다 쓸 수 있는 무기가 있습니다. 지금 무기로 쓸 수 없는 룬은 흐리게 보이고, 카드에 필요한 무기가 적혀 있습니다.\n장착한 룬을 쓸 수 없는 무기로 바꾸면 기본 공격으로 싸우다가, 맞는 무기를 들면 그 룬으로 돌아갑니다.": "每個技能符文都有可用的武器。當前武器無法使用的符文會顯示為灰暗，卡牌上標有所需武器。\n若換成無法使用已裝備符文的武器，則以基礎攻擊戰鬥，持有匹配武器後恢復使用該符文。",
