        "전투는 자동입니다. 캐릭터가 알아서 걷고 공격합니다.\n지금 할 일은 오른쪽 위 ‘목표’에 나옵니다.\n생명 구슬이 자주 비면 장비와 저항을 점검하세요.\n장비나 룬을 얻으면 그때마다 조작을 안내합니다.": "戰鬥為自動。角色會自行移動並攻擊。\n當前要做的事顯示在右上角的「目標」中。\n若生命球經常見底，請檢查裝備與抗性。\n每當獲得裝備或符文時都會說明操作。",
        "레벨 2가 되어 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.": "達到2級，獲得了技能樹點數。\n請在「技能樹」中選擇與起點相連的節點點亮。",
        "장비나 제작 재화를 처음 얻었습니다.\n‘장비’에서 아이템을 눌러 지금 착용한 장비와 비교하고 착용하세요.": "首次獲得了裝備或製作貨幣。\n請在「裝備」中點擊物品，與當前穿戴的裝備比較並穿戴。",
        '새 스킬룬': '新技能符文',
        "새 룬을 얻었습니다.\n‘스킬룬’에서 룬을 눌러 효과를 보고 공격 룬을 바꿔 보세요.": "獲得了新符文。\n請在「技能符文」中點擊符文查看效果，並嘗試更換攻擊符文。",
        '지도 개방': '地圖開放',
        "다음 액트가 열렸습니다.\n‘지도’에서 지나온 액트로 돌아가 다시 사냥하거나, 마친 액트의 보상을 받을 수 있습니다.": "下一幕已開啟。\n可在「地圖」中返回已走過的幕重新狩獵，或領取已完成幕的獎勵。",
