        '다시 누르면 반환합니다(마름병 포자 1개, 이 키스톤을 선행으로 둔 키스톤이 없을 때).': '再按一次即返還（枯萎病孢子1個，且沒有以此基石為前置的基石時）。',
        '재능 개화(5차 전직)를 하면 할당할 수 있습니다.': '完成天賦綻放（五次轉職）後可分配。',
