        // ── 2026-11-04 표에서 넣음(final5-zh-TW.json) ──
        '이 세계의 모든 생명은 거대한 세계수의 가지로 태어나지만, 뿌리내리지 못한 당신은 정원사의 판결 아래 밑거름의 우물로 버려졌습니다.': '這個世界的一切生命都生為巨大世界樹的枝條，而未能扎根的你，在園丁的判決下被棄入底肥之井。',
        '그러나 썩은 진흙과 부러진 가지들 속에서, 당신은 끝내 숨을 거두지 않고 차가운 눈을 떴습니다.': '然而在腐爛的泥與折斷的枝條之中，你終究沒有斷氣，睜開了冰冷的雙眼。',
        '잔뿌리 매듭을 가르고 오른 중정에서, 부정한 은총의 부제녀가 길을 가로막았습니다.': '在劈開細根之結登上的中庭，不潔恩典的女執事擋住了去路。',
        '그녀의 심장을 꿰뚫었으나 중정 바닥의 황금 수액관이 맥동하자 상처는 순식간에 다시 붙었고, 되살아난 일격에 당신은 아래쪽 허공뿌리로 추락했습니다.': '你刺穿了她的心臟，但中庭地面的黃金樹液管一搏動，傷口瞬間癒合，復活的一擊將你打落到下方的虛空根。',
        '당신이 추락한 허공뿌리 현수림은 잎 하나 없이 말라비틀어져, 바람이 불 때마다 마른 가지들이 서로 부딪혀 울었습니다.': '你墜落的虛空根懸林乾枯得沒有一片葉子，每當風起，乾枝便相互碰撞嗚咽。',
        '중정의 불멸을 지탱하는 황금 길의 수액 수송로가 이 굶주린 숲 너머 미궁으로 이어져 있었습니다.': '支撐中庭不滅的黃金之路的樹液輸送線，穿過這片飢餓的森林通向迷宮。',
        '수액 운반선이 끊기자 부제녀의 상처는 더 이상 아물지 않았습니다.': '樹液運輸線一斷，女執事的傷口再也無法癒合。',
        '피를 토하며 쓰러진 부제녀는 마지막 힘을 짜내어, 떨리는 손가락으로 발밑 깊은 성소 쪽을 가리켰습니다.': '吐血倒下的女執事擠出最後的力氣，用顫抖的手指指向腳下深處的聖所。',
        '가슴을 꿰뚫린 하켄은 쓰러지지 않고, 한참 동안 자신의 상처를 말없이 내려다보았습니다.': '胸口被刺穿的哈肯沒有倒下，久久地默默俯視著自己的傷口。',
        '그는 마지막 생명력을 끌어모아 거대한 받침뿌리들을 맞물렸고, 무너진 중정으로 직행하는 보랏빛 다리를 놓아주었습니다.': '他聚起最後的生命力，將巨大的支撐根咬合在一起，架起一座直通坍塌中庭的紫色橋樑。',
        '수액의 호혜를 잃은 정원사가 마침내 무릎을 꿇고, 그의 거대한 가위가 두 동강 났습니다.': '失去樹液互惠的園丁終於跪倒，他巨大的剪刀斷成兩截。',
        '가위가 부러지는 소리와 함께 발밑의 수액이 거꾸로 솟구치기 시작했고, 바닥에 스민 보랏빛 잔향이 속 빈 줄기를 가리켰습니다.': '隨著剪刀折斷的聲響，腳下的樹液開始倒湧，滲入地面的紫色餘響指向了空心的枝幹。',
        '역류하는 수액을 따라 들어선 큰 줄기 내부의 도시는 이미 양분을 모두 빼앗겨 텅 비어 있었습니다.': '沿著倒流的樹液進入的主幹內城，早已被奪走全部養分，空空如也。',
        '썩어가는 어미나무에서 스스로를 도려내어 탈출하려는 삽목들의 행렬 사이로, 수관으로 향하는 나선 계단이 이어져 있었습니다.': '在從腐爛母樹上剜出自己以圖逃脫的插枝隊列之間，一道通往樹冠的螺旋階梯延伸而上。',
        '줄기 끝을 넘어선 곳에는 침입자의 기억과 그림자를 겹겹이 비추는 하얀 장막의 성소가 펼쳐져 있었습니다.': '越過枝幹盡頭，是層層映照入侵者記憶與影子的白色帷幕聖所。',
        '희미한 촛불이 줄지어 선 통로마다, 누군가 오래전에 지나간 순례의 흔적이 겹겹이 쌓여 있었습니다.': '每條立著微弱燭火的通道裡，層層堆積著某人久遠以前走過的朝聖痕跡。',
        '장막이 걷히자 아래쪽 뿌리에서 끌어올린 모든 수액이 응집된 황금빛 수관이 모습을 드러냈습니다.': '帷幕揭開，凝聚了從下方根部汲取的全部樹液的金色樹冠顯露出來。',
        '바깥의 도끼에 맞서기 위해 잘려 나간 아홉 가지를 하나로 꿰맨 거대한 고치가 수관 중심에서 맥동하고 있었습니다.': '為了對抗外界的斧頭，九根被砍下的枝條縫合為一的巨大之繭，在樹冠中心搏動著。',
        '고치를 지키던 접목의 어머니가 쓰러지자, 고치의 외피에 금이 가며 안쪽에서 낮은 박동이 터져 나왔습니다.': '守護繭的接木之母倒下後，繭的外殼裂開，低沉的搏動從內部迸發。',
        '그 안에서 깨어난 형상이 옅은 금빛 후광을 두른 채 세계수의 가장 높은 차륜으로 날아올랐습니다.': '在其中甦醒的身影披著淡金色的光環，飛向世界樹最高的車輪。',
        '합일의 차륜 위에서 쓰러진 존재가 당신을 향해 힘없이 손을 뻗었습니다.': '在合一之輪上倒下的存在，無力地向你伸出了手。',
        '당신도 몸을 숙여 손을 내밀었지만, 끝내 맞닿지 못한 두 손끝의 한 뼘 틈새 아래로 깊은 혼돈 층계가 입을 열었습니다.': '你也俯身伸出了手，但在終究未能相觸的兩指之間的一拳縫隙下方，深邃的混沌層階張開了口。',
        '우물 바닥에서 몸을 일으켜 문 너머로 나섰을 때, 폭주한 잔뿌리 괴물 둘에게 몰려 신음하는 늙은 드루이드 하켄이 보였습니다.': '你從井底起身跨出門外時，看見老德魯伊哈肯被兩隻暴走的細根怪物逼得呻吟不止。',
        '당신이 무장을 고쳐 쥐고 달려들어 괴물들을 쓰러뜨리자, 기사회생한 노인은 거친 숨을 고르며 중정으로 오르는 통로를 가리켰습니다.': '你重新握緊武器衝上去擊倒怪物後，死裡逃生的老人平復著粗重的呼吸，指向通往中庭的通道。',
