        '부패 수확 (화염, 냉기, 번개 식물 1씩)': '腐敗收穫（火焰、冰霜、閃電植物各1）',
        '균열 수확 (화석 1, 뿌리 1)': '裂隙收穫（化石1、根1）',
        '부적과 고급 수확 제작': '護身符與高級收穫製作',
        '“미궁에서 건진 봉인편린에는 잘려 나간 옛 가지들의 원한이 서려 있어. 네 피를 먹여 깨우면 어떤 갑옷보다 든든한 부적이 되지. 그루터기 함의 식물로 하는 고급 수확 제작은 내가 가르쳐줄 수 있지. 조심해 독성이 강할 거야. 그만큼의 값도 받아야겠고.”': '「從迷宮撈出的封印碎片裡，凝結著被砍下的舊枝的怨念。餵以你的血喚醒，就會成為比任何鎧甲都可靠的護身符。用樹樁匣的植物進行的高級收穫製作，我可以教你。小心，毒性會很強。價錢也得相應地收。」',
        '다음: {act} 「{title}」': '下一個：{act}「{title}」',
        // ── 2026-11-05 v0.3.49 묶음(수확 제작, 배경음, 로그인 화면, 액트 보상 카드)의 글 ──
        '죽은 잔뿌리들이 겹겹이 엉켜 중정으로 오르는 길을 가로막은 지하 성소.': '層層枯死的細根糾纏在一起，擋住了通往中庭之路的地下聖所。',
        '아래쪽 뿌리의 수액을 빨아들여 영원을 유지하는 정원.': '吸取下方根系的樹液來維持永恆的庭園。',
        '수액을 모두 빼앗긴 채 허공에 매달려 말라붙은 뿌리 숲.': '樹液被奪盡，懸在虛空中乾枯的根之森。',
        '하층의 수액을 중정으로 실어 나르는 황금 길의 교차로.': '將下層樹液運往中庭的黃金之路交匯處。',
