        '전투 전술': '戰鬥戰術',
        '액트 3을 클리어하면 무료로 해금됩니다. 기본 공격 대상과 전투 거리를 정하고, 조건에 따라 행동하는 규칙을 만들 수 있습니다.': '通關第3幕後免費解鎖。可設定預設攻擊目標與戰鬥距離，並制定按條件執行的行動規則。',
