        '창공의 탑에서 얻는 별도 재화입니다. 창공을 해금한 뒤 영구 강화에 사용할 수 있습니다. 보유량과 영구 룬 강화는 유지됩니다.': '這是在蒼穹之塔獲得的獨立貨幣。解鎖蒼穹後可用於永久強化。持有數量與永久符文強化都會保留。',
        '각성 룬': '覺醒符文',
