        '스킬트리 공허 칸': '技能樹虛空格',
        '스킬트리에 공허 칸(공허 패시브, 직업 공허 소켓)이 나타납니다. 할당한 공허 칸에 마법의 새싹, 요정의 고리, 황금률로 옵션을 붙일 수 있습니다.': '技能樹中會出現虛空格（虛空被動、職業虛空插槽）。可用魔法新芽、妖精之環、黃金律為已分配的虛空格添加詞綴。',
        '공허 칸의 할당과 옵션': '虛空格的分配狀態與詞綴',
