        '주얼 보관함, 장비 소켓의 주얼(루프 봉인 장비는 유지), 주얼 재료': '珠寶儲物箱、裝備插槽中的珠寶（循環封印的裝備會保留）與珠寶材料',
        '그루터기 함 옵션': '樹樁匣詞綴',
